import React, { useState } from 'react';
import Sidebar from './Sidebar';
import UploadSection from './UploadSection';
import SimplifySection from './SimplifySection';
import SummarizeSection from './SummarizeSection';
import KeyPointsSection from './KeyPointsSection';
import QASection from './QASection';

export default function Dashboard() {
  const [activeTab, setActiveTab] = useState('simplify');
  const [originalText, setOriginalText] = useState('');
  const [simplifiedText, setSimplifiedText] = useState('');
  const [summary, setSummary] = useState('');
  const [keyPoints, setKeyPoints] = useState([]);
  const [qaHistory, setQaHistory] = useState([]);

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col">
      <header className="bg-blue-700 text-white p-4 text-2xl font-bold shadow">
        SmartExplain – Document Simplifier
      </header>
      <div className="flex flex-1">
        <Sidebar activeTab={activeTab} setActiveTab={setActiveTab} />
        <main className="flex-1 p-6">
          <UploadSection setOriginalText={setOriginalText} />
          {activeTab === 'simplify' && (
            <SimplifySection originalText={originalText} simplifiedText={simplifiedText} setSimplifiedText={setSimplifiedText} />
          )}
          {activeTab === 'summarize' && (
            <SummarizeSection originalText={originalText} summary={summary} setSummary={setSummary} />
          )}
          {activeTab === 'keypoints' && (
            <KeyPointsSection originalText={originalText} keyPoints={keyPoints} setKeyPoints={setKeyPoints} />
          )}
          {activeTab === 'qa' && (
            <QASection originalText={originalText} qaHistory={qaHistory} setQaHistory={setQaHistory} />
          )}
        </main>
      </div>
    </div>
  );
}
